```javascript
function findMatchingOption(option, searchKey) {
    // Check if the provided key exists in the current level of the option
    if (option[searchKey]) {
        console.log(`Found match: ${searchKey} = ${option[searchKey]}`);
        return option;
    }

    // Recursively check for matching keys at deeper levels
    const options = Object.keys(option).map(key => {
        const nextOption = option[key];
        return findMatchingOption(nextOption, searchKey);
    });

    // Return any found matches from all possible paths
    return options.filter(option => option !== null && typeof option === 'object');
}

